void solve(int edge_idx, vector<int> &vertex_value, vector<bool> &used_domino) {
    if (edge_idx == m) {
        int cnt = 0;
        for (int i = 0; i < m; i++) {
            if (used_domino[i]) cnt++;
        }
        best = max(best, cnt);
        return;
    }

    // Skip this edge
    solve(edge_idx + 1, vertex_value, used_domino);

    // Try placing a domino on this edge
    int u = edges[edge_idx].first;
    int v = edges[edge_idx].second;

    for (int a = 1; a <= 6; a++) {
        for (int b = a; b <= 6; b++) {
            // Check if domino (a, b) is available
            bool domino_available = true;
            for (int i = 0; i < edge_idx; i++) {
                if (used_domino[i]) {
                    int prev_u = edges[i].first;
                    int prev_v = edges[i].second;
                    if ((vertex_value[prev_u] == a && vertex_value[prev_v] == b) ||
                        (vertex_value[prev_u] == b && vertex_value[prev_v] == a)) {
                        domino_available = false;
                        break;
                    }
                }
            }
            if (!domino_available) continue;

            // Check if placing domino (a, b) on edge (u, v) is valid
            bool valid = true;
            if (vertex_value[u] != 0 && vertex_value[u] != a) valid = false;
            if (vertex_value[v] != 0 && vertex_value[v] != b) valid = false;

