                vector<int> new_vertex_value = vertex_value;
                vector<bool> new_used_domino = used_domino;
                new_vertex_value[u] = a;
                new_vertex_value[v] = b;
                new_used_domino[edge_idx] = true;
                solve(edge_idx + 1, new_vertex_value, new_used_domino);
            }

            // Also try domino (b, a) if a != b
            if (a != b) {
                valid = true;
